private void permute(int[] nums, boolean[] used, List<Integer> list, List<List<Integer>> result) {
    if (list.size() == nums.length) {
        result.add(new ArrayList<>(list));
        return;
    }
    for (int i = 0; i < nums.length; i++) {
        if (used[i]) continue;
        used[i] = true;
        list.add(nums[i]);
        permute(nums, used, list, result);
        used[i] = false;
        list.remove(list.size() - 1);
    }
}
