private int findLargestCommonSubstring(String s1, String s2) {
    int largestSubstring = 0;
    for (int i = 0; i < s1.length(); i++) {
        for (int j = 0; j < s2.length(); j++) {
            int substring = 0;
            while (i + substring < s1.length() && j + substring < s2.length() && s1.charAt(i + substring) == s2.charAt(j + substring)) {
                substring++;
            }
            if (substring > largestSubstring) {
                largestSubstring = substring;
            }
        }
    }
    return largestSubstring;
}
