private static void dfs(char[][] grid, boolean[][] visited, int i, int j) {
    visited[i][j] = true;
    if (i > 0 && grid[i - 1][j] == '@' && !visited[i - 1][j]) {
        dfs(grid, visited, i - 1, j);
    }
    if (i < grid.length - 1 && grid[i + 1][j] == '@' && !visited[i + 1][j]) {
        dfs(grid, visited, i + 1, j);
    }
    if (j > 0 && grid[i][j - 1] == '@' && !visited[i][j - 1]) {
        dfs(grid, visited, i, j - 1);
    }
    if (j < grid[0].length - 1 && grid[i][j + 1] == '@' && !visited[i][j + 1]) {
        dfs(grid, visited, i, j + 1);
    }
}
