public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    // Initialize a set to store the visited n-tersections
    Set<Integer> visited = new HashSet<>();

    // Mark the starting n-tersection as visited
    visited.add(start[0] * n + start[1]);

    // Create a queue to store the n-tersections to be visited
    Queue<int[]> queue = new ArrayDeque<>();

    // Enqueue the starting n-tersection
    queue.offer(start);

    // Loop until the queue is empty
    while (!queue.isEmpty()) {
        // Dequeue the current n-tersection
        int[] current = queue.poll();

        // Check if the current n-tersection is the ending n-tersection
        if (current[0] == end[0] && current[1] == end[1]) {
            return "can be travelled";
        }

        // Loop through the paths from the current n-tersection
        for (int[] path : paths) {
            // Check if the path is valid and has not been visited yet
            if (path[0] == current[0] && path[1] == current[1] && !visited.contains((path[0] + path[1]) * (path[0] + path[1] + 1) / 2 + path[1])) {
