    int century = year / 100;
    int yearOfTheCentury = year % 100;
    int dayOfTheWeek = (century / 4) - 2 * century + ((5 * yearOfTheCentury) / 4) + ((26 * (month + 1)) / 10) + day - 1;
    dayOfTheWeek = dayOfTheWeek % 7;
    // Return the formatted weekday
    return months[month - 1] + " " + day + ", " + year + " is a " + weekdays[dayOfTheWeek];
