public int findMinFibonacciNumbers(int k) {
    int fib1 = 1, fib2 = 1, fibres = 0, res = 0;
    while (k > 0) {
        if (k >= fib1) {
            k -= fib1;
            res++;
            fibres = fib1;
        }
        int fibnext = fib1 + fib2;
        fib1 = fib2;
        fib2 = fibnext;
    }
    return res + (k == fibres ? 1 : 0);
}
