public class BagReach {
    public Map<Integer, Integer> calculate(int[] bagWeights, int[] bagCosts, int weightToReach) {
        // map to store weight vs cost result
        Map<Integer, Integer> result = new HashMap<>();

        // sort the bags by their weight in descending order (we want to process the heaviest bags first)
        Arrays.sort(bagWeights, (a, b) -> b - a);
        Arrays.sort(bagCosts, (a, b) -> b - a);

        // traverse through the bags in a loop
        for (int bagWeight : bagWeights) {
            while (weightToReach > 0 && weightToReach >= bagWeight) {
                result.put(bagWeight, result.getOrDefault(bagWeight, 0) + 1);
                weightToReach -= bagWeight;
            }
        }

        // calculate the total cost
        int totalCost = 0;
        for (Map.Entry<Integer, Integer> entry : result.entrySet()) {
            totalCost += entry.getKey() * entry.getValue();
        }
        result.put(Integer.MAX_VALUE, totalCost);
        return result;
    }
}
