public static String minAddToMakeValid(String S) {
    Stack<Character> stack = new Stack<>();
    for (int i = 0; i < S.length(); i++) {
        if (S.charAt(i) == '(') {
            stack.push('(');
        } else {
            if (stack.isEmpty()) {
                return "";
            } else {
                stack.pop();
            }
        }
    }
    StringBuilder sb = new StringBuilder();
    for (Character c : stack) {
        sb.append(c);
    }
    return sb.toString();
}
