public int calculateYearsToEmergency(int studentCount, int ensureEmergencyCreditsAtEachCampus, int creditSpreadPerStudent) {
    int totalEmergencyCredits = 3 * ensureEmergencyCreditsAtEachCampus;
    int totalCreditsPerStudent = studentCount / 3 * creditSpreadPerStudent;
    int totalYears = 0;
    while (totalEmergencyCredits > 0) {
        totalYears++;
        totalEmergencyCredits -= totalCreditsPerStudent;
    }
    return totalYears;
}
