public static List<Integer> findSteppingNumbers(int low, int high) {
    List<Integer> result = new ArrayList<>();
    for (int i = low; i <= high; i++) {
        int j = i + 1;
        while (j > 0) {
            if (j > high) {
                break;
            }
            int k = i - 1;
            while (k > 0) {
                if (k < low) {
                    break;
                }
                if (j == i + 1 && k == i + 1) {
                    continue;
                }
                if (j != k) {
                    break;
                }
                result.add(j);
                break;
            }
            j++;
        }
    }
    return result;
}
