private static boolean isSteppingNumber(int i) {
    int n = i;
    int prev = 0;
    while (n > 0) {
        int curr = n % 10;
        n /= 10;
        if (curr - prev != 1 && curr - prev != -1) {
            return false;
        }
        prev = curr;
    }
    return true;
}
