public static int squarePermutations(int[] A) {
    int n = A.length;
    int[][] dp = new int[n][n];
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            dp[i][j] = -1;
        }
    }
    int result = 0;
    for (int mask = 0; mask < (1 << n); mask++) {
        int valid = 1;
        for (int i = 0; i < n; i++) {
            if (((mask >> i) & 1) == 0) {
                continue;
            }
            for (int j = 0; j < i; j++) {
                if (((mask >> j) & 1) == 0) {
                    continue;
                }
                int diff = A[i] - A[j];
                if (diff < 0 || diff * diff > A[i] || dp[i][j] == -1) {
                    valid = 0;
                    break;
                }
                dp[i][j] = valid;
            }
        }
        if (valid == 1) {
            result++;
        }
    }
    return result;
}
