        int j = i - 1;
        while (j >= 0 && heights[j] >= heights[i]) {
            j = left[j];
        }
        left[i] = j;
    }

    for (int i = n - 2; i >= 0; i--) {
        int j = i + 1;
        while (j < n && heights[j] >= heights[i]) {
            j = right[j];
        }
        right[i] = j;
    }

    for (int i = 0; i < n; i++) {
        area[i] = heights[i] * (right[i] - left[i] - 1);
        maxArea = Math.max(maxArea, area[i]);
